package com.sabyeguyz.clinic.staff; import com.sabyeguyz.clinic.auth.AppUser; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="staff") public class Staff { @Id private Long id; @OneToOne @MapsId @JoinColumn(name="id") private AppUser user; @Column(name="employee_code") private String employeeCode; @Column(name="full_name") private String fullName; private String phone; @Column(name="created_at") private Instant createdAt=Instant.now(); protected Staff(){} public Staff(AppUser u,String code,String name,String phone){user=u;employeeCode=code;fullName=name;this.phone=phone;} public Long getId(){return id;} public String getEmployeeCode(){return employeeCode;} public String getFullName(){return fullName;} }
